+
+ed25519.etc.sha512Async = async (...messages: Uint8Array[]): Promise<Uint8Array> => {
+  const digest = createHash('sha512').update(Buffer.concat(messages.map((message) => Buffer.from(message)))).digest();
+  return new Uint8Array(digest);
+};
